CREATE TABLE IF NOT EXISTS restaurant_config (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS restaurant_customers (phone TEXT PRIMARY KEY, name TEXT NOT NULL DEFAULT 'Guest', points INTEGER NOT NULL DEFAULT 0, visits INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'New', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS restaurant_orders (id TEXT PRIMARY KEY, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'Pending', verified BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_restaurant_orders_created ON restaurant_orders(created_at DESC);
CREATE TABLE IF NOT EXISTS restaurant_tables (number INTEGER PRIMARY KEY, seats INTEGER NOT NULL DEFAULT 4, status TEXT NOT NULL DEFAULT 'Available', updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS restaurant_bookings (id TEXT PRIMARY KEY, payload JSONB NOT NULL, status TEXT NOT NULL DEFAULT 'Booked', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());